cat >> tests/vitest/window-child-ownership.test.ts <<'EOF'

/** Window ids in PAINTED order, lowest z-index first. */
function paintOrder( manager: WindowManager ): string[] {
	return [ ...manager._stack ]
		.sort(
			( a, b ) =>
				Number( a.element.style.zIndex ) - Number( b.element.style.zIndex ),
		)
		.map( ( w ) => w.id );
}

describe( 'keep on top — a layer above focus order', () => {
	let desktop: HTMLElement;
	let manager: WindowManager;

	beforeEach( () => {
		installHooksStub();
		desktop = makeDesktop();
		document.body.appendChild( desktop );
		manager = new WindowManager( desktop );
	} );

	afterEach( () => {
		for ( const w of manager.getAll() ) {
			w.destroy();
		}
		desktop.remove();
		clearHooksStub();
	} );

	test( 'stays painted above a window that is focused or opened after it', async () => {
		const pinned = await manager.open( cfg( 'pinned' ) );
		const other = await manager.open( cfg( 'other' ) );
		expect( manager.setAlwaysOnTop( 'pinned', true ) ).toBe( true );
		expect( pinned.alwaysOnTop ).toBe( true );

		manager.focus( other );
		const fresh = await manager.open( cfg( 'fresh' ) );

		// Focus is untouched by the flag: the new window has it…
		expect( fresh.isFocused() ).toBe( true );
		expect( manager.getFocused()?.id ).toBe( 'fresh' );
		// …but paints underneath the kept-on-top one.
		expect( paintOrder( manager ) ).toEqual( [ 'other', 'fresh', 'pinned' ] );
	} );

	test( 'several stack among themselves by focus, and off restores normal stacking', async () => {
		await manager.open( cfg( 'a' ) );
		await manager.open( cfg( 'b' ) );
		await manager.open( cfg( 'plain' ) );
		manager.setAlwaysOnTop( 'a', true );
		manager.setAlwaysOnTop( 'b', true );

		manager.focus( 'a' );
		manager.focus( 'plain' );
		expect( paintOrder( manager ) ).toEqual( [ 'plain', 'b', 'a' ] );

		manager.setAlwaysOnTop( 'a', false );
		manager.setAlwaysOnTop( 'b', false );
		expect( paintOrder( manager ) ).toEqual( [ 'b', 'a', 'plain' ] );
		expect( manager.setAlwaysOnTop( 'nope', true ) ).toBe( false );
	} );

	test( 'a child of a kept-on-top owner stays above that owner', async () => {
		await manager.open( cfg( 'owner' ) );
		await manager.openChild( 'owner', cfg( 'child' ) );
		manager.setAlwaysOnTop( 'owner', true );

		await manager.open( cfg( 'other' ) );

		expect( paintOrder( manager ) ).toEqual( [ 'other', 'owner', 'child' ] );
	} );

	test( 'the title-bar pin toggles it, reflects it, and the session carries it', async () => {
		registerBuiltInControls();
		try {
			const win = await manager.open( cfg( 'pinme' ) );
			const pin = (): HTMLElement =>
				win.element.querySelector< HTMLElement >(
					'.os-window__btn--always-on-top',
				)!;
			expect( pin().getAttribute( 'aria-pressed' ) ).toBe( 'false' );

			pin().dispatchEvent( new CustomEvent( 'os-button-activate' ) );
			expect( win.alwaysOnTop ).toBe( true );
			expect( pin().getAttribute( 'aria-pressed' ) ).toBe( 'true' );

			// A controls repaint rebuilds the button; the state must
			// survive it.
			win.repaintWindowControls();
			expect( pin().getAttribute( 'aria-pressed' ) ).toBe( 'true' );
			expect( manager.snapshot().windows[ 0 ].alwaysOnTop ).toBe( true );

			pin().dispatchEvent( new CustomEvent( 'os-button-activate' ) );
			expect( win.alwaysOnTop ).toBe( false );
			expect( manager.snapshot().windows[ 0 ] ).not.toHaveProperty( 'alwaysOnTop' );
		} finally {
			for ( const id of [ 'always-on-top', 'minimize', 'maximize', 'focus-tab', 'close' ] ) {
				unregisterWindowControl( `core/${ id }` );
			}
		}
	} );
} );
EOF
